"""Задачи для задачника (ru/en/es). Используется tools/make_practice.py.

Поля задачи:
  id, kind (predict | fix | write | think | project), level (1..3),
  text / hint / answer: {lang: html},
  code: str или {lang: str}  — стартовый код (если есть),
  run: можно ли запускать на странице, canvas: показывать холст,
  answer_code: str или {lang: str} — код ответа,
  expect: str или {lang: str} — что должна вывести программа (проверяется тестом).
"""

SETUP = 'let canvas = document.getElementById("game");\nlet ctx = canvas.getContext("2d");\n'

SECTIONS = []


def section(key, title, lessons, tasks):
    SECTIONS.append({"key": key, "title": title, "lessons": lessons, "tasks": tasks})


def L(ru, en, es):
    return {"ru": ru, "en": en, "es": es}


