         answer_code=SETUP + '\nlet x = 180;\nlet y = 180;\n\nfunction draw() {\n  ctx.fillStyle = "black";\n  ctx.fillRect(0, 0, 400, 400);\n  ctx.fillStyle = "lime";\n  ctx.fillRect(x, y, 40, 40);\n}\n\nfunction onKey(event) {\n  if (event.key === "ArrowUp") {\n    y = y - 20;\n  }\n  if (event.key === "ArrowDown") {\n    y = y + 20;\n  }\n  if (event.key === "ArrowLeft") {\n    x = x - 20;\n  }\n  if (event.key === "ArrowRight") {\n    x = x + 20;\n  }\n  draw();\n}\n\ndocument.addEventListener("keydown", onKey);\ndraw();',
